"""Embedded configuration UI HTML."""

CONFIG_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1" />\n  <title>Canvas Event Webhooks</title>\n  <style>\n    :root {\n      --bg: #f4f6f8;\n      --card: #ffffff;\n      --text: #1c2430;\n      --muted: #5b6775;\n      --border: #d7dee6;\n      --accent: #0b6e4f;\n      --accent-hover: #08563e;\n      --danger: #b42318;\n      --danger-bg: #fef3f2;\n      --ok: #027a48;\n      --ok-bg: #ecfdf3;\n      --warn: #b54708;\n      --warn-bg: #fffaeb;\n      --focus: #0b6e4f;\n      --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 1px 3px rgba(16, 24, 40, 0.1);\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0;\n      font-family: "Segoe UI", system-ui, -apple-system, sans-serif;\n      background: var(--bg);\n      color: var(--text);\n      line-height: 1.45;\n    }\n    .wrap { max-width: 860px; margin: 0 auto; padding: 28px 20px 64px; }\n    h1 { font-size: 1.5rem; margin: 0 0 6px; }\n    .lede { color: var(--muted); margin: 0 0 24px; }\n    .banner {\n      border-radius: 8px;\n      padding: 10px 14px;\n      margin: 0 0 16px;\n      font-size: 0.95rem;\n    }\n    .banner.error { background: var(--danger-bg); color: var(--danger); }\n    .banner.ok { background: var(--ok-bg); color: var(--ok); }\n    .banner.warn { background: var(--warn-bg); color: var(--warn); }\n    .hidden { display: none !important; }\n    .card {\n      background: var(--card);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      box-shadow: var(--shadow);\n      padding: 20px;\n      margin-bottom: 16px;\n    }\n    .card-head {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      margin-bottom: 16px;\n    }\n    .card-head h2 { font-size: 1.05rem; margin: 0; }\n    .toggle { display: flex; align-items: center; gap: 8px; font-size: 0.9rem; }\n    .details-box {\n      margin: 0 0 12px;\n      padding: 10px 12px;\n      background: #f8fafc;\n      border: 1px solid var(--border);\n      border-radius: 8px;\n    }\n    .hint { color: var(--muted); font-size: 0.8rem; margin: 6px 0 0; }\n    label.field { display: block; font-weight: 600; font-size: 0.85rem; margin: 12px 0 6px; }\n    input[type="text"], input[type="url"] {\n      width: 100%;\n      padding: 8px 10px;\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      font: inherit;\n    }\n    input:focus { outline: 2px solid var(--focus); outline-offset: 1px; }\n    .secret-row { display: flex; gap: 8px; }\n    .secret-row input { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.85rem; }\n    .btn {\n      border: 1px solid var(--border);\n      background: #fff;\n      color: var(--text);\n      border-radius: 8px;\n      padding: 8px 12px;\n      font: inherit;\n      cursor: pointer;\n      white-space: nowrap;\n    }\n    .btn:hover:not(:disabled) { background: #f8fafc; }\n    .btn:disabled { opacity: 0.5; cursor: not-allowed; }\n    .btn.primary { background: var(--accent); color: #fff; border-color: var(--accent); }\n    .btn.primary:hover:not(:disabled) { background: var(--accent-hover); }\n    .btn.danger { color: var(--danger); border-color: #fecdca; background: var(--danger-bg); }\n    .actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }\n    .count { color: var(--muted); font-size: 0.9rem; margin: 8px 0 4px; }\n    .events { border: 1px solid var(--border); border-radius: 8px; padding: 8px 10px; max-height: 360px; overflow: auto; }\n    .select-all { font-weight: 600; padding: 6px 0 10px; border-bottom: 1px solid var(--border); margin-bottom: 8px; }\n    .cat { margin: 8px 0; }\n    .cat-head { font-weight: 600; display: flex; align-items: center; gap: 8px; }\n    .cat-events { margin: 4px 0 8px 22px; display: grid; gap: 4px; }\n    .check { display: flex; align-items: center; gap: 8px; font-weight: 400; }\n    .footer-bar {\n      display: flex; align-items: center; justify-content: space-between;\n      gap: 12px; margin-top: 8px; flex-wrap: wrap;\n    }\n    .muted { color: var(--muted); }\n    .legacy { font-size: 0.85rem; background: var(--warn-bg); color: var(--warn); padding: 8px 10px; border-radius: 8px; margin-bottom: 12px; }\n  </style>\n</head>\n<body>\n  <div class="wrap">\n    <h1>Canvas Event Webhooks</h1>\n    <p class="lede">Configure where Canvas events should be sent. You can set up to three independent destinations. Each destination only receives the events you select. Optionally include who did it, the patient name, and major record details.</p>\n    <div id="flash" class="banner hidden" role="status"></div>\n    <div id="cards"></div>\n    <div class="footer-bar">\n      <button type="button" class="btn primary" id="addBtn">+ Add Webhook</button>\n      <span class="muted" id="quota"></span>\n    </div>\n  </div>\n  <script>\n    const API = new URL(".", window.location.href);\n    let catalog = [];\n    let webhooks = [];\n    let drafts = [];\n    let maxWebhooks = 3;\n\n    const $ = (id) => document.getElementById(id);\n\n    function flash(kind, message) {\n      const el = $("flash");\n      el.className = "banner " + kind;\n      el.textContent = message;\n      el.classList.remove("hidden");\n    }\n    function clearFlash() { $("flash").classList.add("hidden"); }\n\n    async function api(path, options = {}) {\n      const res = await fetch(new URL(path, API), {\n        credentials: "same-origin",\n        headers: { "Content-Type": "application/json", ...(options.headers || {}) },\n        ...options,\n      });\n      const text = await res.text();\n      let data = null;\n      try { data = text ? JSON.parse(text) : null; } catch { data = { error: text }; }\n      if (!res.ok) throw new Error((data && data.error) || res.statusText);\n      return data;\n    }\n\n    function applyList(data) {\n      if (Array.isArray(data && data.webhooks)) {\n        webhooks = data.webhooks;\n        return true;\n      }\n      return false;\n    }\n\n    function allEventNames() {\n      return catalog.flatMap((c) => c.events.map((e) => e.name));\n    }\n\n    function eventCount(selected) {\n      const n = (selected || []).length;\n      return n + " event" + (n === 1 ? "" : "s") + " selected";\n    }\n\n    function render() {\n      const cards = $("cards");\n      cards.innerHTML = "";\n      const items = [...webhooks, ...drafts];\n      items.forEach((wh, index) => cards.appendChild(renderCard(wh, index + 1)));\n      const used = items.length;\n      $("quota").textContent = used + " / " + maxWebhooks + " webhooks configured";\n      $("addBtn").disabled = used >= maxWebhooks;\n      $("addBtn").title = used >= maxWebhooks ? "Maximum of 3 webhooks configured." : "Add another webhook";\n    }\n\n    function renderCard(wh, n) {\n      const card = document.createElement("div");\n      card.className = "card";\n      card.dataset.id = wh.id || ("draft-" + n);\n\n      const selected = new Set(wh.events || []);\n      const allNames = allEventNames();\n\n      const head = document.createElement("div");\n      head.className = "card-head";\n      head.innerHTML = `<h2>Webhook ${n}</h2>`;\n      const toggle = document.createElement("label");\n      toggle.className = "toggle";\n      toggle.innerHTML = `<input type="checkbox" class="js-enabled" ${wh.enabled !== false ? "checked" : ""}> Enabled`;\n      head.appendChild(toggle);\n      card.appendChild(head);\n\n      const detailsBox = document.createElement("div");\n      detailsBox.className = "details-box";\n      detailsBox.innerHTML = `\n        <label class="toggle">\n          <input type="checkbox" class="js-details" ${wh.include_details ? "checked" : ""}>\n          Include names and details\n        </label>\n        <p class="hint">Adds a description, who performed the action, the patient name, and major record fields (time, status, title, provider).</p>\n      `;\n      card.appendChild(detailsBox);\n\n      if (wh.legacy) {\n        const note = document.createElement("div");\n        note.className = "legacy";\n        note.textContent = "This webhook comes from CLI secrets (webhook-url). Save it here to manage it in the UI. After saving, the UI configuration takes precedence.";\n        card.appendChild(note);\n      }\n\n      card.insertAdjacentHTML("beforeend", `\n        <label class="field">Name</label>\n        <input type="text" class="js-name" maxlength="80" placeholder="Production API" value="${escapeAttr(wh.name || "")}">\n        <label class="field">Webhook URL</label>\n        <input type="url" class="js-url" placeholder="https://example.com/webhooks/canvas" value="${escapeAttr(wh.url || "")}">\n        <label class="field">Webhook Secret</label>\n        <div class="secret-row">\n          <input type="text" class="js-secret" readonly value="${escapeAttr(wh.secret || (wh.id ? "" : "Generated automatically when you save"))}">\n          <button type="button" class="btn js-copy" ${wh.secret ? "" : "disabled"}>Copy</button>\n          <button type="button" class="btn js-regen" ${wh.id ? "" : "disabled"}>Regenerate</button>\n        </div>\n        <div class="count js-count">${eventCount([...selected])}</div>\n        <label class="field">Events</label>\n      `);\n\n      const eventsBox = document.createElement("div");\n      eventsBox.className = "events";\n\n      const selectAll = document.createElement("label");\n      selectAll.className = "select-all check";\n      const selectAllCb = document.createElement("input");\n      selectAllCb.type = "checkbox";\n      selectAllCb.className = "js-select-all";\n      selectAll.appendChild(selectAllCb);\n      selectAll.appendChild(document.createTextNode(" Select All Events"));\n      eventsBox.appendChild(selectAll);\n\n      catalog.forEach((cat) => {\n        const wrap = document.createElement("div");\n        wrap.className = "cat";\n        const headL = document.createElement("label");\n        headL.className = "cat-head check";\n        const catCb = document.createElement("input");\n        catCb.type = "checkbox";\n        catCb.className = "js-cat";\n        catCb.dataset.key = cat.key;\n        headL.appendChild(catCb);\n        headL.appendChild(document.createTextNode(" " + cat.label));\n        wrap.appendChild(headL);\n        const list = document.createElement("div");\n        list.className = "cat-events";\n        cat.events.forEach((ev) => {\n          const l = document.createElement("label");\n          l.className = "check";\n          const cb = document.createElement("input");\n          cb.type = "checkbox";\n          cb.className = "js-event";\n          cb.value = ev.name;\n          cb.dataset.cat = cat.key;\n          cb.checked = selected.has(ev.name);\n          l.appendChild(cb);\n          l.appendChild(document.createTextNode(" " + ev.label));\n          list.appendChild(l);\n        });\n        wrap.appendChild(list);\n        eventsBox.appendChild(wrap);\n      });\n      card.appendChild(eventsBox);\n\n      const actions = document.createElement("div");\n      actions.className = "actions";\n      actions.innerHTML = `\n        <button type="button" class="btn js-test" ${wh.id && wh.url ? "" : "disabled"}>Test Webhook</button>\n        <button type="button" class="btn primary js-save">Save</button>\n        <button type="button" class="btn danger js-delete">${wh.id && !String(wh.id).startsWith("draft") ? "Delete" : "Remove"}</button>\n      `;\n      card.appendChild(actions);\n\n      function readSelected() {\n        return [...card.querySelectorAll(".js-event:checked")].map((el) => el.value);\n      }\n      function syncChecks() {\n        const sel = new Set(readSelected());\n        card.querySelector(".js-count").textContent = eventCount([...sel]);\n        const allCb = card.querySelector(".js-select-all");\n        allCb.checked = allNames.length > 0 && allNames.every((n) => sel.has(n));\n        allCb.indeterminate = !allCb.checked && allNames.some((n) => sel.has(n));\n        card.querySelectorAll(".js-cat").forEach((catCb) => {\n          const names = catalog.find((c) => c.key === catCb.dataset.key).events.map((e) => e.name);\n          const nSel = names.filter((n) => sel.has(n)).length;\n          catCb.checked = names.length > 0 && nSel === names.length;\n          catCb.indeterminate = nSel > 0 && nSel < names.length;\n        });\n      }\n      syncChecks();\n\n      selectAllCb.addEventListener("change", () => {\n        card.querySelectorAll(".js-event").forEach((cb) => { cb.checked = selectAllCb.checked; });\n        syncChecks();\n      });\n      card.querySelectorAll(".js-cat").forEach((catCb) => {\n        catCb.addEventListener("change", () => {\n          card.querySelectorAll(`.js-event[data-cat="${catCb.dataset.key}"]`).forEach((cb) => {\n            cb.checked = catCb.checked;\n          });\n          syncChecks();\n        });\n      });\n      card.querySelectorAll(".js-event").forEach((cb) => cb.addEventListener("change", syncChecks));\n\n      card.querySelector(".js-copy").addEventListener("click", async () => {\n        const secret = card.querySelector(".js-secret").value;\n        try {\n          await navigator.clipboard.writeText(secret);\n          flash("ok", "Secret copied.");\n        } catch {\n          flash("error", "Could not copy automatically. Select the secret and copy it manually.");\n        }\n      });\n\n      card.querySelector(".js-regen").addEventListener("click", async () => {\n        if (!confirm("Generate a new secret? Your receiver must be updated to the new value.")) return;\n        try {\n          const data = await api("webhooks/" + encodeURIComponent(wh.id) + "/regenerate", { method: "POST" });\n          if (!applyList(data)) replaceWebhook(wh, data.webhook);\n          flash("ok", "Secret regenerated.");\n          render();\n        } catch (err) { flash("error", err.message); }\n      });\n\n      card.querySelector(".js-save").addEventListener("click", async () => {\n        clearFlash();\n        const url = card.querySelector(".js-url").value.trim();\n        if (url.toLowerCase().startsWith("http://")) {\n          flash("error", "URL must use HTTPS. HTTP is not allowed.");\n          return;\n        }\n        const payload = {\n          name: card.querySelector(".js-name").value,\n          url: url,\n          events: readSelected(),\n          enabled: card.querySelector(".js-enabled").checked,\n          include_details: card.querySelector(".js-details").checked,\n        };\n        try {\n          let data;\n          if (!wh.id) {\n            data = await api("webhooks", { method: "POST", body: JSON.stringify(payload) });\n            drafts = drafts.filter((d) => d !== wh);\n            if (!applyList(data)) webhooks.push(data.webhook);\n          } else {\n            data = await api("webhooks/" + encodeURIComponent(wh.id), { method: "PUT", body: JSON.stringify(payload) });\n            if (!applyList(data)) replaceWebhook(wh, data.webhook);\n          }\n          flash(data.warning ? "warn" : "ok", data.warning || "Webhook saved.");\n          render();\n        } catch (err) { flash("error", err.message); }\n      });\n\n      card.querySelector(".js-delete").addEventListener("click", async () => {\n        if (!confirm("Remove this webhook? It will stop receiving events.")) return;\n        try {\n          if (wh.id && !String(wh.id).startsWith("draft")) {\n            const data = await api("webhooks/" + encodeURIComponent(wh.id), { method: "DELETE" });\n            if (!applyList(data)) webhooks = webhooks.filter((w) => w.id !== wh.id);\n          } else {\n            drafts = drafts.filter((d) => d !== wh);\n          }\n          flash("ok", "Webhook removed.");\n          render();\n        } catch (err) { flash("error", err.message); }\n      });\n\n      card.querySelector(".js-test").addEventListener("click", async () => {\n        try {\n          const data = await api("webhooks/" + encodeURIComponent(wh.id) + "/test", { method: "POST" });\n          flash(data.warning ? "warn" : "ok", data.warning ? data.message + " " + data.warning : data.message);\n        } catch (err) { flash("error", err.message); }\n      });\n\n      return card;\n    }\n\n    function replaceWebhook(oldWh, next) {\n      const i = webhooks.findIndex((w) => w === oldWh || w.id === oldWh.id);\n      if (i >= 0) webhooks[i] = next;\n      else webhooks.push(next);\n    }\n\n    function escapeAttr(value) {\n      return String(value).replace(/[&<>"\']/g, (ch) => ({\n        "&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;", "\'": "&#39;"\n      }[ch]));\n    }\n\n    $("addBtn").addEventListener("click", () => {\n      if (webhooks.length + drafts.length >= maxWebhooks) {\n        flash("warn", "Maximum of 3 webhooks configured.");\n        return;\n      }\n      drafts.push({ id: null, name: "", url: "", secret: "", enabled: true, include_details: false, events: [], draft: true });\n      clearFlash();\n      render();\n    });\n\n    (async function init() {\n      try {\n        const cat = await api("catalog");\n        catalog = cat.categories || [];\n        const list = await api("webhooks");\n        webhooks = list.webhooks || [];\n        maxWebhooks = list.max || 3;\n        render();\n      } catch (err) {\n        flash("error", err.message || "Could not load webhook configuration.");\n      }\n    })();\n  </script>\n</body>\n</html>\n'
